/** Each example's own file, by registry id. */
export const EXAMPLE_SOURCES: Record<string, string> = {
  "activity-heatmap-deploys": "\"use client\";\n\nimport ActivityHeatmap, { type ActivityDay } from \"./activity-heatmap\";\n\nconst END = Date.parse(\"2026-11-05\");\n\n// a steady, seeded year: busier midweek, quiet at weekends\nlet seed = 7;\nconst random = () => {\n  seed = (seed * 9301 + 49297) % 233280;\n  return seed / 233280;\n};\n\nconst data: ActivityDay[] = Array.from({ length: 371 }, (_, index) => {\n  const time = END - index * 86_400_000;\n  const weekend = [0, 6].includes(new Date(time).getUTCDay());\n  const wave = 0.5 + 0.5 * Math.sin((index / 371) * Math.PI * 3);\n  const count = Math.round(random() * (weekend ? 3 : 10) * (0.4 + wave));\n  return { date: new Date(time).toISOString().slice(0, 10), count };\n});\n\nexport default function ActivityHeatmapDeploys() {\n  return (\n    <ActivityHeatmap\n      data={data}\n      end=\"2026-11-05\"\n      label=\"Deploys\"\n      unit=\"deploys\"\n      size=\"sm\"\n      weeks={46}\n    />\n  );\n}\n",
  "autocomplete-grouped": "import Autocomplete, { type AutocompleteGroup } from \"./autocomplete\";\n\nexport default function AutocompleteGrouped() {\n  return (\n    <Autocomplete\n      items={cityGroups}\n      label=\"Advanced search\"\n      placeholder=\"Search by city or country\"\n    />\n  );\n}\n\nconst cityGroups: AutocompleteGroup[] = [\n  {\n    group: \"Europe\",\n    items: [\n      { label: \"Athens\", description: \"Greece\" },\n      { label: \"Berlin\", description: \"Germany\" },\n      { label: \"Lisbon\", description: \"Portugal\" },\n    ],\n  },\n  {\n    group: \"Africa\",\n    items: [\n      { label: \"Cairo\", description: \"Egypt\" },\n      { label: \"Dakar\", description: \"Senegal\" },\n      { label: \"Nairobi\", description: \"Kenya\" },\n    ],\n  },\n  {\n    group: \"Asia\",\n    items: [\n      { label: \"Osaka\", description: \"Japan\" },\n      { label: \"Seoul\", description: \"South Korea\" },\n      { label: \"Taipei\", description: \"Taiwan\" },\n    ],\n  },\n];\n",
  "autocomplete-helper": "import Autocomplete, { type AutocompleteItem } from \"./autocomplete\";\n\nexport default function AutocompleteHelper() {\n  return (\n    <Autocomplete\n      items={cities}\n      label={\n        <>\n          City <span className=\"c:red-5\">*</span>\n        </>\n      }\n      placeholder=\"Search cities\"\n      description=\"Start typing to narrow the list.\"\n    />\n  );\n}\n\nconst cities: AutocompleteItem[] = [\n  \"Athens\",\n  \"Berlin\",\n  \"Cairo\",\n  \"Dakar\",\n  \"Helsinki\",\n  \"Lisbon\",\n  \"Nairobi\",\n  \"Osaka\",\n  \"Quito\",\n  \"Reykjavik\",\n  \"Seville\",\n  \"Valparaiso\",\n].map((label) => ({ label }));\n",
  "autocomplete-icon-leading": "import { IconBell, IconHelpCircle, IconKey, IconSearch, IconSettings, IconUserX, IconWorld } from \"@tabler/icons-react\";\nimport Autocomplete, { type AutocompleteItem } from \"./autocomplete\";\n\nexport default function AutocompleteIconLeading() {\n  return (\n    <Autocomplete\n      items={settings}\n      label=\"Search settings\"\n      placeholder=\"Account, Privacy, & more\"\n      icon={<IconSearch className=\"w:4 h:4\" />}\n      iconPosition=\"leading\"\n      emptyMessage=\"No settings found.\"\n    />\n  );\n}\n\nconst settings: AutocompleteItem[] = [\n  { label: \"Account Settings\", icon: <IconSettings className=\"w:4 h:4\" /> },\n  { label: \"Privacy & Security\", icon: <IconKey className=\"w:4 h:4\" /> },\n  {\n    label: \"Notifications\",\n    icon: <IconBell className=\"w:4 h:4\" />,\n  },\n  { label: \"Language & Region\", icon: <IconWorld className=\"w:4 h:4\" /> },\n  { label: \"Blocked Accounts\", icon: <IconUserX className=\"w:4 h:4\" /> },\n  { label: \"Help Center\", icon: <IconHelpCircle className=\"w:4 h:4\" /> },\n];\n",
  "autocomplete-icon-trailing": "import { IconBell, IconHelpCircle, IconKey, IconSearch, IconSettings, IconUserX, IconWorld } from \"@tabler/icons-react\";\nimport Autocomplete, { type AutocompleteItem } from \"./autocomplete\";\n\nexport default function AutocompleteIconTrailing() {\n  return (\n    <Autocomplete\n      items={settings}\n      label=\"Search settings\"\n      placeholder=\"Account, Privacy, & more\"\n      icon={<IconSearch className=\"w:4 h:4\" />}\n      iconPosition=\"trailing\"\n      emptyMessage=\"No settings found.\"\n    />\n  );\n}\n\nconst settings: AutocompleteItem[] = [\n  { label: \"Account Settings\", icon: <IconSettings className=\"w:4 h:4\" /> },\n  { label: \"Privacy & Security\", icon: <IconKey className=\"w:4 h:4\" /> },\n  {\n    label: \"Notifications\",\n    icon: <IconBell className=\"w:4 h:4\" />,\n  },\n  { label: \"Language & Region\", icon: <IconWorld className=\"w:4 h:4\" /> },\n  { label: \"Blocked Accounts\", icon: <IconUserX className=\"w:4 h:4\" /> },\n  { label: \"Help Center\", icon: <IconHelpCircle className=\"w:4 h:4\" /> },\n];\n",
  "avatar-icon-fallback": "import Avatar, { type AvatarProps } from \"./avatar\";\n\nexport default function AvatarIconFallback() {\n  return (\n    <div className=\"d:f ai:c g:4\">\n      {tints.map((tint) => (\n        <Avatar key={tint} tint={tint} />\n      ))}\n    </div>\n  );\n}\n\nconst tints: NonNullable<AvatarProps[\"tint\"]>[] = [\"accent\", \"mint\", \"indigo\"];\n",
  "avatar-initial-fallback": "import Avatar, { type AvatarProps } from \"./avatar\";\n\nexport default function AvatarFallbackInitial() {\n  return (\n    <div className=\"d:f ai:c g:4\">\n      {tints.map((tint) => (\n        <Avatar key={tint} fallback=\"ME\" tint={tint} />\n      ))}\n    </div>\n  );\n}\n\nconst tints: NonNullable<AvatarProps[\"tint\"]>[] = [\"accent\", \"mint\", \"indigo\"];\n",
  "avatar-stack-compact": "import { IconDeviceLaptop, IconDeviceMobile, IconDeviceTablet } from \"@tabler/icons-react\";\nimport Avatar from \"./avatar\";\n\nexport default function AvatarStackCompact() {\n  return (\n    <div className=\"d:f ai:c p:px bg:raised bs-o:key bc:rim br:9999 bw:1\">\n      {devices.map((device, index) => (\n        <Avatar\n          key={device.name}\n          size=\"sm\"\n          name={device.name}\n          fallback={<device.icon className=\"w:4 h:4\" />}\n          className={index > 0 ? \"ml:-2\" : \"\"}\n        />\n      ))}\n      <Avatar size=\"sm\" fallback={`+${extraCount}`} className=\"ml:-2\" />\n    </div>\n  );\n}\n\nconst devices = [\n  { name: \"This laptop\", icon: IconDeviceLaptop },\n  { name: \"Phone\", icon: IconDeviceMobile },\n  { name: \"Tablet\", icon: IconDeviceTablet },\n];\n\nconst extraCount = 1;\n",
  "button-group-split": "\"use client\";\n\nimport {\n  IconChevronDown,\n  IconDownload,\n  IconFileTypePdf,\n  IconFileZip,\n  IconLinkPlus,\n} from \"@tabler/icons-react\";\nimport Button from \"./button\";\nimport ButtonGroup from \"./button-group\";\nimport Menu from \"./menu\";\n\nexport default function ButtonGroupSplit({\n  container,\n}: {\n  container?: HTMLElement | null;\n}) {\n  return (\n    <ButtonGroup>\n      <Button icon={<IconDownload className=\"w:4 h:4\" />}>Download</Button>\n      <Menu\n        container={container}\n        trigger={\n          <Button icon={<IconChevronDown className=\"w:4 h:4\" />} iconOnly>\n            Download options\n          </Button>\n        }\n        items={[\n          {\n            label: \"Download as PDF\",\n            icon: <IconFileTypePdf className=\"w:4 h:4\" />,\n          },\n          {\n            label: \"Download as ZIP\",\n            icon: <IconFileZip className=\"w:4 h:4\" />,\n          },\n          { type: \"separator\" },\n          { label: \"Copy link\", icon: <IconLinkPlus className=\"w:4 h:4\" /> },\n        ]}\n      />\n    </ButtonGroup>\n  );\n}\n",
  "combobox-grouped": "import Combobox, { type ComboboxGroup } from \"./combobox\";\n\nexport default function ComboboxGrouped() {\n  return (\n    <Combobox\n      items={cityGroups}\n      label=\"Advanced search\"\n      placeholder=\"Search by city or country\"\n      emptyMessage=\"No cities found.\"\n    />\n  );\n}\n\nconst cityGroups: ComboboxGroup[] = [\n  {\n    group: \"Europe\",\n    items: [\n      { label: \"Athens\", description: \"Greece\" },\n      { label: \"Berlin\", description: \"Germany\" },\n      { label: \"Lisbon\", description: \"Portugal\" },\n    ],\n  },\n  {\n    group: \"Africa\",\n    items: [\n      { label: \"Cairo\", description: \"Egypt\" },\n      { label: \"Dakar\", description: \"Senegal\" },\n      { label: \"Nairobi\", description: \"Kenya\" },\n    ],\n  },\n  {\n    group: \"Asia\",\n    items: [\n      { label: \"Osaka\", description: \"Japan\" },\n      { label: \"Seoul\", description: \"South Korea\" },\n      { label: \"Taipei\", description: \"Taiwan\" },\n    ],\n  },\n];\n",
  "combobox-helper": "import Combobox, { type ComboboxItem } from \"./combobox\";\n\nexport default function ComboboxHelper() {\n  return (\n    <Combobox\n      items={cities}\n      label={\n        <>\n          City <span className=\"c:red-5\">*</span>\n        </>\n      }\n      placeholder=\"Search cities\"\n      description=\"Start typing to narrow the list.\"\n      emptyMessage=\"No cities found.\"\n    />\n  );\n}\n\nconst cities: ComboboxItem[] = [\n  \"Athens\",\n  \"Berlin\",\n  \"Cairo\",\n  \"Dakar\",\n  \"Helsinki\",\n  \"Lisbon\",\n  \"Nairobi\",\n  \"Osaka\",\n  \"Quito\",\n  \"Reykjavik\",\n  \"Seville\",\n  \"Valparaiso\",\n].map((label) => ({ label }));\n",
  "field-invite": "\"use client\";\n\nimport { IconSend } from \"@tabler/icons-react\";\nimport { useState } from \"react\";\nimport Button from \"./button\";\nimport Field from \"./field\";\nimport Form from \"./form\";\n\nexport default function FieldInvite() {\n  const [success, setSuccess] = useState<string>();\n\n  return (\n    <Form\n      className=\"d:f fd:r ai:fs g:2 w:80 max-w:100%\"\n      onSubmit={({ email }) => {\n        const address = typeof email === \"string\" ? email.trim() : \"\";\n        setSuccess(undefined);\n        // the browser accepts an address with no ending, so the form checks it\n        if (!/\\.[a-z]{2,}$/i.test(address))\n          return { email: \"Add the ending after the dot, such as .com or .dev.\" };\n        setSuccess(`Invite sent to ${address}.`);\n      }}\n    >\n      <div className=\"f:1 min-w:0\">\n        <Field\n          name=\"email\"\n          type=\"email\"\n          label=\"Email\"\n          defaultValue=\"grace@hopper\"\n          description=\"We send the invite here.\"\n          success={success}\n          onChange={() => setSuccess(undefined)}\n          className=\"w:100%\"\n          required\n        />\n      </div>\n      {/* one label line and the field's gap, so the key lines up with the input */}\n      <div className=\"fs:sm pt:calc(1lh)\">\n        <Button type=\"submit\" icon={<IconSend className=\"w:4 h:4\" />} iconOnly className=\"mt:2\">\n          Send invite\n        </Button>\n      </div>\n    </Form>\n  );\n}\n",
  "field-prefix": "import Field from \"./field\";\n\nexport default function FieldPrefix() {\n  return (\n    <Field\n      label=\"Custom domain\"\n      placeholder=\"yummacss.com/ui\"\n      prefixNode=\"https://\"\n    />\n  );\n}\n",
  "field-suffix": "import Field from \"./field\";\n\nexport default function FieldSuffix() {\n  return <Field label=\"Email\" placeholder=\"john@yummaui\" suffix=\".com\" />;\n}\n",
  "otp-field-verify": "\"use client\";\n\nimport { useState } from \"react\";\nimport OTPField from \"./otp-field\";\n\nconst CODE = \"204816\";\n\nexport default function OTPFieldVerify() {\n  const [tries, setTries] = useState(3);\n  const [error, setError] = useState<string>();\n  const [success, setSuccess] = useState<string>();\n\n  return (\n    <OTPField\n      label=\"Verification code\"\n      description=\"Sent to your phone. Here, the code is 204816.\"\n      error={error}\n      success={success}\n      onValueChange={(code) => {\n        // typing again takes the old error away, so the next wrong code shakes anew\n        if (code.length > 0 && code.length < CODE.length) setError(undefined);\n        if (code.length < CODE.length) return;\n        if (code === CODE) {\n          setError(undefined);\n          setSuccess(\"Verified\");\n          return;\n        }\n        const left = Math.max(tries - 1, 0);\n        setTries(left);\n        setError(\n          left > 0\n            ? `That code did not work. ${left} ${left === 1 ? \"try\" : \"tries\"} left.`\n            : \"That code did not work. Request a new one.\",\n        );\n      }}\n    />\n  );\n}\n",
  "popover-folder-color": "\"use client\";\n\nimport { IconPalette } from \"@tabler/icons-react\";\nimport { useState } from \"react\";\nimport Button from \"./button\";\nimport Popover from \"./popover\";\n\nconst COLORS = [\n  { name: \"Yellow\", swatch: \"bg:yellow h:bg:yellow\", ink: \"c:yellow\" },\n  { name: \"Pink\", swatch: \"bg:pink h:bg:pink\", ink: \"c:pink\" },\n  { name: \"Violet\", swatch: \"bg:violet h:bg:violet\", ink: \"c:violet\" },\n  { name: \"Blue\", swatch: \"bg:blue h:bg:blue\", ink: \"c:blue\" },\n  { name: \"Mint\", swatch: \"bg:mint h:bg:mint\", ink: \"c:mint\" },\n  { name: \"Slate\", swatch: \"bg:slate h:bg:slate\", ink: \"c:slate\" },\n];\n\nexport default function PopoverFolderColor({\n  container,\n}: {\n  container?: HTMLElement | null;\n}) {\n  const [color, setColor] = useState(COLORS[0]);\n\n  return (\n    <Popover\n      trigger={<IconPalette className={`w:4 h:4 ${color.ink}`} />}\n      triggerLabel=\"Folder color\"\n      triggerVariant=\"label\"\n      title=\"Taxes\"\n      container={container}\n    >\n      <div className=\"d:f g:2 pt:1\">\n        {COLORS.map((entry) => {\n          const picked = entry.name === color.name;\n          return (\n            <Button\n              key={entry.name}\n              aria-label={entry.name}\n              aria-pressed={picked}\n              onClick={() => setColor(entry)}\n              className={`w:6 h:6 p:0 br:9999 bw:1 bc:black/15 bs-o:none ${entry.swatch} ${\n                picked ? \"os:s ow:2 oo:2 oc:label\" : \"\"\n              }`}\n            />\n          );\n        })}\n      </div>\n    </Popover>\n  );\n}\n",
  "progress-upload": "\"use client\";\n\nimport { IconClock } from \"@tabler/icons-react\";\nimport { useEffect, useState } from \"react\";\nimport Button from \"./button\";\nimport Progress from \"./progress\";\n\n// an upload moves in bursts and stalls between them, so each step is a chunk\n// and a wait, not a steady tick\nconst STEPS = [\n  { to: 6, after: 600 },\n  { to: 19, after: 900 },\n  { to: 35, after: 800 },\n  { to: 51, after: 2200 },\n  { to: 58, after: 700 },\n  { to: 74, after: 1100 },\n  { to: 88, after: 1600 },\n  { to: 96, after: 900 },\n  { to: 100, after: 1300 },\n];\n\nexport default function ProgressUpload() {\n  const [step, setStep] = useState(0);\n  const [paused, setPaused] = useState(false);\n  const value = step === 0 ? 0 : STEPS[step - 1].to;\n  const done = step === STEPS.length;\n\n  useEffect(() => {\n    if (paused || done) return;\n    const timer = setTimeout(() => setStep(step + 1), STEPS[step].after);\n    return () => clearTimeout(timer);\n  }, [paused, done, step]);\n\n  const seconds = Math.ceil(\n    STEPS.slice(step).reduce((total, next) => total + next.after, 0) / 1000,\n  );\n\n  return (\n    <div className=\"d:g g:3 w:100% max-w:64\">\n      <Progress\n        value={value}\n        label={done ? \"Uploaded 5 of 5 files\" : \"Uploading 5 files\"}\n      />\n      <div className=\"d:f ai:c jc:sb\">\n        <span className=\"d:f ai:c g:1 fs:sm c:hint fvn:tn\">\n          <IconClock className=\"w:4 h:4\" />\n          {done ? \"Done\" : paused ? \"Paused\" : `About ${seconds} seconds left`}\n        </span>\n        <Button\n          variant=\"secondary\"\n          size=\"sm\"\n          onClick={() => {\n            if (done) {\n              setStep(0);\n              setPaused(false);\n            } else setPaused(!paused);\n          }}\n        >\n          {done ? \"Start again\" : paused ? \"Resume\" : \"Pause\"}\n        </Button>\n      </div>\n    </div>\n  );\n}\n",
  "scroll-area-files": "\"use client\";\n\nimport { IconArchive, IconFile, IconPhoto, IconVideo } from \"@tabler/icons-react\";\nimport ScrollArea from \"./scroll-area\";\nimport { RADIUS, useShape } from \"./style\";\n\nconst files = [\n  { Icon: IconFile, name: \"budget.xlsx\", size: \"24 KB\" },\n  { Icon: IconFile, name: \"readme.md\", size: \"3 KB\" },\n  { Icon: IconPhoto, name: \"scan-0412.png\", size: \"1.2 MB\" },\n  { Icon: IconPhoto, name: \"beach.jpg\", size: \"3.4 MB\" },\n  { Icon: IconVideo, name: \"holiday.mov\", size: \"860 MB\" },\n  { Icon: IconFile, name: \"notes.txt\", size: \"1 KB\" },\n  { Icon: IconArchive, name: \"receipts.zip\", size: \"18 MB\" },\n  { Icon: IconFile, name: \"tax-return.pdf\", size: \"412 KB\" },\n  { Icon: IconPhoto, name: \"passport.jpg\", size: \"2.1 MB\" },\n  { Icon: IconFile, name: \"recipes.md\", size: \"6 KB\" },\n  { Icon: IconVideo, name: \"birthday.mov\", size: \"1.2 GB\" },\n  { Icon: IconArchive, name: \"old-photos.zip\", size: \"4.6 GB\" },\n  { Icon: IconFile, name: \"packing-list.txt\", size: \"2 KB\" },\n  { Icon: IconPhoto, name: \"wallpaper.png\", size: \"5.8 MB\" },\n];\n\nexport default function ScrollAreaFiles() {\n  const shape = useShape(undefined, [\"square\", \"rounded\", \"squircle\"] as const);\n  return (\n    <div\n      className={`d:f fd:c w:80 max-w:100% bg:raised bs-o:key bw:1 bc:rim c:label o:h ${RADIUS.popup[shape]}`}\n    >\n      <div className=\"d:f ai:b jc:sb px:4 pt:3 pb:2\">\n        <span className=\"fs:sm fw:500\">Downloads</span>\n        <span className=\"c:hint fs:xs\">14 files</span>\n      </div>\n      <div className=\"h:0 btw:1 bc:line\" />\n      <ScrollArea shape={shape} className=\"h:64\">\n        <div className=\"d:f fd:c p:1 pr:3\">\n          {files.map(({ Icon, name, size }) => (\n            <div\n              key={name}\n              className={`d:f ai:c g:3 h:8 px:2 fs:sm h:bg:well ${RADIUS.item[shape]}`}\n            >\n              <Icon className=\"w:4 h:4 c:label\" />\n              <span className=\"f:1\">{name}</span>\n              <span className=\"c:hint fs:xs\">{size}</span>\n            </div>\n          ))}\n        </div>\n      </ScrollArea>\n    </div>\n  );\n}\n",
  "select-grouped": "import Select, { type SelectGroup } from \"./select\";\n\nexport default function SelectGrouped() {\n  return (\n    <Select\n      options={categories}\n      label=\"Task Category\"\n      placeholder=\"Select category...\"\n    />\n  );\n}\n\nconst categories: SelectGroup[] = [\n  {\n    group: \"Development\",\n    items: [\n      { label: \"Bug\", value: \"bug\" },\n      { label: \"Feature\", value: \"feature\" },\n      { label: \"Enhancement\", value: \"enhancement\" },\n    ],\n  },\n  {\n    group: \"Project\",\n    items: [\n      { label: \"Documentation\", value: \"documentation\" },\n      { label: \"Design\", value: \"design\" },\n      { label: \"Research\", value: \"research\" },\n    ],\n  },\n];\n",
  "skeleton-activity": "import Skeleton from \"./skeleton\";\n\nconst ENTRIES = Array.from({ length: 4 }, (_, i) => ({ id: `activity-${i}` }));\n\nexport default function SkeletonActivity() {\n  return (\n    <div className=\"d:f fd:c g:4 p:8 h:56\">\n      {ENTRIES.map((entry, row) => (\n        <div key={entry.id} className=\"d:f ai:c g:4\">\n          <Skeleton\n            shape=\"circle\"\n            dimensions=\"w:9 h:9\"\n            delay={row * 0.15}\n            className=\"fs:0\"\n          />\n          <div className=\"d:f fd:c g:1 fg:1\">\n            <Skeleton dimensions=\"h:3 w:48\" delay={row * 0.15} />\n            <Skeleton tone=\"subtle\" dimensions=\"h:2 w:32\" delay={row * 0.15} />\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n",
  "skeleton-filters": "import Skeleton from \"./skeleton\";\n\nexport default function SkeletonFilters() {\n  return (\n    <div className=\"d:f fd:c g:4 p:8 h:56\">\n      <Skeleton shape=\"block\" dimensions=\"h:10 w:100%\" />\n      <div className=\"d:f g:2\">\n        <Skeleton shape=\"circle\" dimensions=\"h:6 w:16\" delay={0.05} />\n        <Skeleton shape=\"circle\" dimensions=\"h:6 w:20\" delay={0.1} />\n        <Skeleton shape=\"circle\" dimensions=\"h:6 w:14\" delay={0.15} />\n      </div>\n      <Skeleton tone=\"subtle\" dimensions=\"h:3 w:24\" delay={0.2} />\n      <div className=\"d:f ai:c g:4\">\n        <Skeleton\n          shape=\"block\"\n          dimensions=\"w:9 h:9\"\n          delay={0.25}\n          className=\"fs:0\"\n        />\n        <div className=\"d:f fd:c g:1 fg:1\">\n          <Skeleton dimensions=\"h:3 w:48\" delay={0.25} />\n          <Skeleton tone=\"subtle\" dimensions=\"h:2 w:32\" delay={0.25} />\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "skeleton-list": "import Skeleton from \"./skeleton\";\n\nexport default function SkeletonList() {\n  return (\n    <div className=\"d:f fd:c g:4 p:8 h:56\">\n      {[0, 1, 2].map((row) => (\n        <div key={row} className=\"d:f ai:c g:4\">\n          {}\n          <Skeleton shape=\"block\" dimensions=\"w:9 h:9\" delay={row * 0.15} />\n          <div className=\"d:f fd:c g:1 fg:1\">\n            <Skeleton dimensions=\"h:3 w:40\" delay={row * 0.15} />\n            <Skeleton tone=\"subtle\" dimensions=\"h:2 w:24\" delay={row * 0.15} />\n          </div>\n        </div>\n      ))}\n    </div>\n  );\n}\n",
  "skeleton-stats": "import Skeleton from \"./skeleton\";\n\nconst CARDS = Array.from({ length: 3 }, (_, i) => ({ id: `card-${i}` }));\n\nexport default function SkeletonStats() {\n  return (\n    <div className=\"d:f g:6 p:8 h:56\">\n      {CARDS.map((card, column) => (\n        <div key={card.id} className=\"d:f fd:c ai:c jc:c g:3 fg:1\">\n          <Skeleton\n            shape=\"block\"\n            dimensions=\"w:10 h:10\"\n            delay={column * 0.15}\n          />\n          <Skeleton dimensions=\"h:6 w:16\" delay={column * 0.15} />\n          <Skeleton tone=\"subtle\" dimensions=\"h:3 w:12\" delay={column * 0.15} />\n        </div>\n      ))}\n    </div>\n  );\n}\n",
  "stat-live": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport Stat from \"./stat\";\n\nconst format = new Intl.NumberFormat(\"en-US\");\n\nexport default function StatLive() {\n  const [photos, setPhotos] = useState([2840, 2911, 2967, 3012, 3088, 3140, 3196, 3248]);\n\n  // a backup in progress: a few photos land every couple of seconds\n  useEffect(() => {\n    const timer = setInterval(\n      () => setPhotos((now) => [...now.slice(1), now[now.length - 1] + 3 + Math.round(Math.random() * 37)]),\n      2200,\n    );\n    return () => clearInterval(timer);\n  }, []);\n\n  const latest = photos[photos.length - 1];\n  const growth = ((latest - photos[0]) / photos[0]) * 100;\n\n  return (\n    <Stat\n      label=\"Photos backed up\"\n      value={format.format(latest)}\n      change={`${growth.toFixed(1)}%`}\n      direction=\"up\"\n      tone=\"positive\"\n      trend={photos}\n      className=\"w:64\"\n    />\n  );\n}\n",
  "tooltip-toolbar": "\"use client\";\n\nimport { IconCopy, IconPencil, IconTrash } from \"@tabler/icons-react\";\nimport Tooltip from \"./tooltip\";\nimport { RADIUS, useShape, type Shape } from \"./style\";\n\nconst ACTIONS = [\n  { label: \"Rename\", shortcut: \"F2\", Icon: IconPencil },\n  { label: \"Duplicate\", shortcut: \"Ctrl D\", Icon: IconCopy },\n  { label: \"Move to Trash\", shortcut: \"Del\", Icon: IconTrash },\n];\n\nexport default function TooltipToolbar({\n  shape: shapeProp,\n  container,\n}: {\n  shape?: Shape;\n  container?: HTMLElement | null;\n}) {\n  const shape = useShape(shapeProp);\n  return (\n    <div\n      className={`d:f g:1 p:1 bw:1 bg:raised bc:rim bs-o:key ${RADIUS.bar[shape]}`}\n    >\n      {ACTIONS.map(({ label, shortcut, Icon }) => (\n        <Tooltip\n          key={label}\n          trigger={<Icon className=\"w:4 h:4\" />}\n          triggerLabel={label}\n          content={label}\n          shortcut={shortcut}\n          tone=\"dark\"\n          shape={shape}\n          container={container}\n        />\n      ))}\n    </div>\n  );\n}\n",
};
